    },
    {
      "role": "user",
      "content": {{ JSON.stringify(JSON.stringify($json.body)) }}
    }
  ]
}

parameters.jsCode:
// Estrae il JSON prodotto da GPT-4o-mini e prepara i campi per Telegram ed email
const contenuto = $json.choices?.[0]?.message?.content ?? '{}';
let lead;
try {
  lead = JSON.parse(contenuto);
} catch (e) {
  lead = { nome: null, telefono: null, email: null, tipo_lavoro: 'altro', urgenza: 1, riassunto: 'Estrazione non riuscita: controllare il log.' };
}
const livello = Math.min(Math.max(parseInt(lead.urgenza) || 1, 1), 5);
const pallini = '🔴'.repeat(livello) + '⚪'.repeat(5 - livello);
const ora = new Date().toLocaleString('it-IT', { timeZone: 'Europe/Rome' });
return [{ json: { ...lead, urgenza: livello, pallini, ora } }];

